const x=864e5;export function dayOfYear(t){return Math.floor((new Date(t.getFullYear(),t.getMonth(),t.getDate())-new Date(t.getFullYear(),0,1))/864e5)}export function isDaylightSaving(t){const n=new Date(t.getFullYear(),0,1).getTimezoneOffset(),o=new Date(t.getFullYear(),6,1).getTimezoneOffset();return t.getTimezoneOffset()<Math.max(n,o)}export function sunTimes(t){const o=6.1+1.3*Math.cos(2*Math.PI*(dayOfYear(t)-172)/365),e=11.95+(isDaylightSaving(t)?1:0);return{sunrise:e-o,sunset:e+o}}const u=t=>{const n=Math.min(1,Math.max(0,t));return n*n*(3-2*n)};export function mix(t,n,o){const e=Math.min(1,Math.max(0,o)),a=(s,c)=>s>>c&255,r=s=>Math.round(a(t,s)+(a(n,s)-a(t,s))*e);return r(16)<<16|r(8)<<8|r(0)}export function css(t){return`#${t.toString(16).padStart(6,"0")}`}export function lightAt(t,n=null){const o=n??t.getHours()+t.getMinutes()/60,{sunrise:e,sunset:a}=sunTimes(t),r=Math.min(u((o-e+.5)/1),u((a+.5-o)/1));let s="day";return r<=0?s="night":r<1&&(s=o<12?"dawn":"dusk"),{hour:o,daylight:r,phase:s,key:`${s}:${Math.round(r*8)}`}}const i={top:726320,bottom:2764618,sun:10466559},f={top:5208499,bottom:15905402,sun:16757611},h={top:8368861,bottom:14937327,sun:16773336};export function lighting(t){const n=t.daylight,o=t.phase==="dawn"||t.phase==="dusk"?Math.sin(n*Math.PI):0,e=a=>mix(mix(i[a],h[a],n),f[a],o*.7);return{skyTop:e("top"),skyBottom:e("bottom"),sunColor:e("sun"),sun:.12+1.4*n,hemi:.22+.7*n,fill:.12+.23*n,cityLights:1-n,cityNear:mix(1844019,5991293,n),cityFar:mix(2436160,8690093,n)}}
